import csv
import io


def parse_csv(raw_csv: str):
    source = io.StringIO(raw_csv.removeprefix("\ufeff"), newline="")
    at_record_start = True

    def physical_lines():
        nonlocal at_record_start
        for line in source:
            if at_record_start and (
                line.lstrip().startswith("#") or not line.strip()
            ):
                continue
            at_record_start = False
            yield line

    reader = csv.reader(
        physical_lines(), delimiter=",", quotechar='"', doublequote=True
    )

    # The registry has one CSV header; the surrounding comments document it.
    columns = next(reader, None)
    if columns is None:
        return {"columns": [], "rows": []}

    rows = []
    width = max(4, len(columns))
    while True:
        at_record_start = True
        row = next(reader, None)
        if row is None:
            break
        rows.append(row)
        width = max(width, len(row))

    used_names = set(columns)
    for position in range(len(columns) + 1, width + 1):
        name = f"extra_{position}"
        while name in used_names:
            name += "_"
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
